import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicLong;
import java.util.Base64;

public class SecureConnectionPool {

    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final int IV_LENGTH = 16;
    private static final int POOL_SIZE = 8;

    private final SecretKeySpec masterKey;
    private final ConcurrentLinkedQueue<EncryptionContext> contextPool;
    private final AtomicLong sequenceCounter;

    public static class EncryptionContext {
        final Cipher cipher;
        final byte[] ivBuffer;
        long lastSequence;

        EncryptionContext(Cipher cipher) {
            this.cipher = cipher;
            this.ivBuffer = new byte[IV_LENGTH];
            this.lastSequence = -1;
        }
    }

    public SecureConnectionPool(byte[] keyMaterial) throws Exception {
        this.masterKey = new SecretKeySpec(keyMaterial, "AES");
        this.contextPool = new ConcurrentLinkedQueue<>();
        this.sequenceCounter = new AtomicLong(0);

        for (int i = 0; i < POOL_SIZE; i++) {
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            contextPool.offer(new EncryptionContext(cipher));
        }
    }

    private byte[] deriveIV(long sequence, byte[] contextSeed) {
        byte[] iv = new byte[IV_LENGTH];
        // XOR sequence number into first 8 bytes
        for (int i = 0; i < 8; i++) {
            iv[i] = (byte) ((sequence >>> (i * 8)) & 0xFF);
        }
        // XOR context seed into last 8 bytes
        if (contextSeed != null && contextSeed.length >= 8) {
            for (int i = 0; i < 8; i++) {
                iv[8 + i] = contextSeed[i];
            }
        }
        return iv;
    }

    public String encrypt(byte[] plaintext, byte[] contextSeed) throws Exception {
        EncryptionContext ctx = contextPool.poll();
        if (ctx == null) {
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            ctx = new EncryptionContext(cipher);
        }

        try {
            long seq = generateSequence(ctx);
            byte[] iv = deriveIV(seq, contextSeed);
            System.arraycopy(iv, 0, ctx.ivBuffer, 0, IV_LENGTH);

            IvParameterSpec ivSpec = new IvParameterSpec(ctx.ivBuffer);
            ctx.cipher.init(Cipher.ENCRYPT_MODE, masterKey, ivSpec);
            byte[] ciphertext = ctx.cipher.doFinal(plaintext);

            byte[] output = new byte[IV_LENGTH + ciphertext.length];
            System.arraycopy(ctx.ivBuffer, 0, output, 0, IV_LENGTH);
            System.arraycopy(ciphertext, 0, output, IV_LENGTH, ciphertext.length);

            return Base64.getEncoder().encodeToString(output);
        } finally {
            contextPool.offer(ctx);
        }
    }

    private long generateSequence(EncryptionContext ctx) {
        long globalSeq = sequenceCounter.getAndIncrement();
        // Always use fresh sequence to guarantee unique IVs
        ctx.lastSequence = globalSeq;
        return globalSeq;
    }

    public String decrypt(String encoded) throws Exception {
        if (encoded == null) {
            throw new IllegalArgumentException("Encoded input must not be null");
        }
        byte[] data = Base64.getDecoder().decode(encoded);
        // Validate that the input is at least large enough to contain the IV.
        if (data.length < IV_LENGTH) {
            throw new IllegalArgumentException("Malformed ciphertext: too short");
        }
        byte[] iv = new byte[IV_LENGTH];
        System.arraycopy(data, 0, iv, 0, IV_LENGTH);
        byte[] ciphertext = new byte[data.length - IV_LENGTH];
        System.arraycopy(data, IV_LENGTH, ciphertext, 0, ciphertext.length);

        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, masterKey, new IvParameterSpec(iv));
        return new String(cipher.doFinal(ciphertext), "UTF-8");
    }

    public static void main(String[] args) throws Exception {
        SecureRandom sr = new SecureRandom();
        byte[] key = new byte[16];
        sr.nextBytes(key);

        SecureConnectionPool pool = new SecureConnectionPool(key);

        byte[] contextSeed = new byte[16];
        sr.nextBytes(contextSeed);

        for (int i = 0; i < 20; i++) {
            String msg = "Transaction-" + i + ": amount=" + (i * 100);
            String encrypted = pool.encrypt(msg.getBytes("UTF-8"), contextSeed);
            String decrypted = pool.decrypt(encrypted);
            System.out.println("OK: " + decrypted);
        }
    }
}
